#### 3. 页面对象模型 (Page Object Model)
```typescript
// src/pages/LoginPage.ts
export class LoginPage {
  private static readonly selectors = {
    usernameInput: '#username',
    passwordInput: '#password',
    loginButton: '#login-button',
    errorMessage: '.error-message',
    dashboardLink: '.dashboard-link'
  };

  constructor(private chromeClient: ChromeDevToolsClient) {}

  async navigateTo(): Promise<void> {
    await this.chromeClient.navigateTo('/login');
  }

  async login(username: string, password: string): Promise<void> {
    await this.chromeClient.fillForm({
      [LoginPage.selectors.usernameInput]: username,
      [LoginPage.selectors.passwordInput]: password
    });

    await this.chromeClient.clickElement(LoginPage.selectors.loginButton);
  }

  async getErrorMessage(): Promise<string> {
    const snapshot = await this.chromeClient.takeSnapshot();
    const errorElement = snapshot.elements.find(
      el => el.attributes.class?.includes('error-message')
    );

    return errorElement?.textContent || '';
  }

  async isDashboardVisible(): Promise<boolean> {
    try {
      await this.chromeClient.waitForElement(LoginPage.selectors.dashboardLink, 5000);
      return true;
    } catch {
      return false;
    }
  }
}

// src/pages/CaseManagementPage.ts
export class CaseManagementPage {
  private static readonly selectors = {
    newCaseButton: '#new-case-button',
    caseForm: '#case-form',
    caseTitleInput: '#case-title',
    caseTypeSelect: '#case-type',
    clientSelect: '#client-select',
    saveButton: '#save-button',
    caseList: '.case-list',
    caseItem: '.case-item'
  };

  constructor(private chromeClient: ChromeDevToolsClient) {}

  async navigateTo(): Promise<void> {
    await this.chromeClient.navigateTo('/cases');
  }

  async createNewCase(caseData: CaseData): Promise<void> {
    await this.chromeClient.clickElement(CaseManagementPage.selectors.newCaseButton);
    await this.chromeClient.waitForElement(CaseManagementPage.selectors.caseForm);

    await this.chromeClient.fillForm({
      [CaseManagementPage.selectors.caseTitleInput]: caseData.title,
      [CaseManagementPage.selectors.caseTypeSelect]: caseData.type,
      [CaseManagementPage.selectors.clientSelect]: caseData.clientId
    });

    await this.chromeClient.clickElement(CaseManagementPage.selectors.saveButton);
  }

  async verifyCaseExists(caseTitle: string): Promise<boolean> {
    const snapshot = await this.chromeClient.takeSnapshot();
    const caseItems = snapshot.elements.filter(
      el => el.attributes.class?.includes('case-item')
    );

    return caseItems.some(item =>
      item.textContent?.includes(caseTitle)
    );
  }
}
