    const generator = new TestDataGenerator(template);
    const testData = await generator.generate();

    // 保存生成的数据
    this.dataStore.set(template.id, testData);

    return testData;
  }

  async cleanupTestData(dataSetId: string): Promise<void> {
    const dataSet = this.dataStore.get(dataSetId);
    if (!dataSet) {
      return;
