// src/core/utils/Logger.ts
export class TestLogger {
  private static instance: TestLogger;
  private logs: TestLog[] = [];

  static getInstance(): TestLogger {
    if (!TestLogger.instance) {
      TestLogger.instance = new TestLogger();
    }
    return TestLogger.instance;
  }

  log(level: LogLevel, message: string, metadata?: any): void {
    const logEntry: TestLog = {
      timestamp: new Date(),
      level,
      message,
      metadata
    };

    this.logs.push(logEntry);

    // 输出到控制台
    console.log(`[${level.toUpperCase()}] ${message}`, metadata || '');
  }

  getLogs(): TestLog[] {
    return [...this.logs];
  }

  exportLogs(format: 'json' | 'csv' = 'json'): string {
    if (format === 'json') {
      return JSON.stringify(this.logs, null, 2);
    } else {
      // CSV格式导出
      const headers = 'timestamp,level,message,metadata';
      const rows = this.logs.map(log =>
        `${log.timestamp.toISOString()},${log.level},"${log.message}","${JSON.stringify(log.metadata)}"`
      );
      return [headers, ...rows].join('\n');
    }
  }
}

